import{_ as a,o as s,c as t,a0 as i}from"./chunks/framework.DhQjJcnt.js";const k=JSON.parse('{"title":"Protocol Specification","description":"","frontmatter":{},"headers":[],"relativePath":"en/protocol.md","filePath":"en/protocol.md","lastUpdated":null}'),n={name:"en/protocol.md"};function o(l,e,r,d,p,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="protocol-specification" tabindex="-1">Protocol Specification <a class="header-anchor" href="#protocol-specification" aria-label="Permalink to &quot;Protocol Specification&quot;">​</a></h1><p>For developers who want a compatible client/server or a deep understanding. All protocols are simple text/binary formats with no encryption (<code>--key</code> encryption lives in the FRS1 layer, see below).</p><h2 id="_1-signaling-rest-api" tabindex="-1">1. Signaling REST API <a class="header-anchor" href="#_1-signaling-rest-api" aria-label="Permalink to &quot;1. Signaling REST API&quot;">​</a></h2><p>Base URL: <code>signaling_addr</code> (e.g. <code>http://host:8080</code>).</p><h3 id="post-room-create" tabindex="-1">POST <code>/room/create</code> <a class="header-anchor" href="#post-room-create" aria-label="Permalink to &quot;POST \`/room/create\`&quot;">​</a></h3><p>Request:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;prefix&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;game&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ttl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">43200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;223.117.153.115:44276&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>prefix</code></td><td>room prefix</td></tr><tr><td><code>ttl</code></td><td>lifetime in seconds</td></tr><tr><td><code>addr</code></td><td>the caller&#39;s public address (learned via UDP probe)</td></tr></tbody></table><p>Response <code>200</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;room_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;game-a3f9c2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;host_addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;223.117.153.115:44276&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h3 id="get-room-id" tabindex="-1">GET <code>/room/{id}</code> <a class="header-anchor" href="#get-room-id" aria-label="Permalink to &quot;GET \`/room/{id}\`&quot;">​</a></h3><p>Response <code>200</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;room_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;game-a3f9c2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;host_addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;223.117.153.115:44276&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;guest_addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;223.117.153.115:44282&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;created_at&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1724900000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expires_at&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1724943200</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>guest_addr</code> is <code>null</code> before a guest joins. Expired rooms return <code>404</code>.</p><h3 id="post-room-id-join" tabindex="-1">POST <code>/room/{id}/join</code> <a class="header-anchor" href="#post-room-id-join" aria-label="Permalink to &quot;POST \`/room/{id}/join\`&quot;">​</a></h3><p>Request:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;223.117.153.115:44282&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Response <code>200</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;room_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;game-a3f9c2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;host_addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;223.117.153.115:44276&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h3 id="delete-room-id" tabindex="-1">DELETE <code>/room/{id}</code> <a class="header-anchor" href="#delete-room-id" aria-label="Permalink to &quot;DELETE \`/room/{id}\`&quot;">​</a></h3><p><code>204</code> on success, <code>404</code> if missing.</p><h3 id="get-health" tabindex="-1">GET <code>/health</code> <a class="header-anchor" href="#get-health" aria-label="Permalink to &quot;GET \`/health\`&quot;">​</a></h3><p>Returns <code>ok</code>.</p><h2 id="_2-udp-public-probe" tabindex="-1">2. UDP public probe <a class="header-anchor" href="#_2-udp-public-probe" aria-label="Permalink to &quot;2. UDP public probe&quot;">​</a></h2><p>The client sends to the probe port (same as HTTP, or <code>signaling_udp</code>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ECHO &lt;token&gt;</span></span></code></pre></div><p>The server echoes (the source address is the client&#39;s NAT-mapped public address):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ADDR &lt;token&gt; &lt;ip&gt;:&lt;port&gt;</span></span></code></pre></div><p><code>token</code> is generated by the client (8 hex chars) to correlate responses.</p><h2 id="_3-hole-punching-protocol" tabindex="-1">3. Hole-punching protocol <a class="header-anchor" href="#_3-hole-punching-protocol" aria-label="Permalink to &quot;3. Hole-punching protocol&quot;">​</a></h2><p>Datagrams are ASCII text:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUNCH &lt;token&gt;   # punch request</span></span>
<span class="line"><span>ACK &lt;token&gt;     # punch confirmation (token echoed)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Scenario</th><th>Behavior</th></tr></thead><tbody><tr><td>receive <code>PUNCH &lt;t&gt;</code></td><td>reply <code>ACK &lt;t&gt;</code> (with retries), record peer address → direct</td></tr><tr><td>receive <code>ACK &lt;t&gt;</code> matching local token</td><td>direct</td></tr><tr><td>receive an FRS1 frame (magic <code>FRS1</code>)</td><td>peer already in data phase → direct</td></tr></tbody></table><p>Punch targets = peer&#39;s advertised address ± spread ports (own port excluded). Window ~3s.</p><h2 id="_4-frs1-reliable-stream-protocol" tabindex="-1">4. FRS1 reliable stream protocol <a class="header-anchor" href="#_4-frs1-reliable-stream-protocol" aria-label="Permalink to &quot;4. FRS1 reliable stream protocol&quot;">​</a></h2><p>UDP datagrams, 15-byte header + payload:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>offset  size  field</span></span>
<span class="line"><span>0       4     magic = &quot;FRS1&quot;</span></span>
<span class="line"><span>4       1     flags: 0x01=DATA, 0x02=FIN, 0=pure ACK</span></span>
<span class="line"><span>5       4     seq (u32 BE)</span></span>
<span class="line"><span>9       4     ack (u32 BE)   — highest contiguous seq received + 1</span></span>
<span class="line"><span>13      2     len (u16 BE)   — payload length</span></span>
<span class="line"><span>15      len   payload (DATA frames; with --key, ciphertext incl. 16B Poly1305 tag)</span></span></code></pre></div><h3 id="sender-state-machine" tabindex="-1">Sender state machine <a class="header-anchor" href="#sender-state-machine" aria-label="Permalink to &quot;Sender state machine&quot;">​</a></h3><ul><li><code>next_seq</code> starts at 1; window is 32 frames</li><li>Data frames enter the window and are sent; windowed frames go into the retransmit queue</li><li>On <code>ack=N</code>: remove all frames with <code>seq &lt; N</code>; when the FIN frame is acked (<code>ack &gt; fin_seq</code>), close completes</li><li>150ms timer: retransmit all unacknowledged windowed frames</li><li>Idle 1s: send a pure ACK (keepalive, keeps NAT mapping alive)</li></ul><h3 id="receiver-state-machine" tabindex="-1">Receiver state machine <a class="header-anchor" href="#receiver-state-machine" aria-label="Permalink to &quot;Receiver state machine&quot;">​</a></h3><ul><li><code>next_expected</code> starts at 1</li><li>Data frame with <code>seq == next_expected</code>: deliver payload, <code>next_expected += 1</code>, reply ACK</li><li>Out-of-order/duplicate frames: drop (go-back-N), still reply ACK to hint the sender</li><li>FIN received: set <code>rx_closed</code>, reply ACK</li><li>Read buffer full (1MB): drop frames without advancing seq (triggers retransmit = flow control)</li></ul><h3 id="encryption" tabindex="-1">Encryption <a class="header-anchor" href="#encryption" aria-label="Permalink to &quot;Encryption&quot;">​</a></h3><p>With <code>--key</code>, DATA payload = <code>ChaCha20-Poly1305.encrypt(nonce=seq, plaintext)</code>; the ciphertext includes a 16-byte auth tag; plaintext frames cap at 1184 bytes. ACK/FIN frames stay plaintext.</p><h3 id="close" tabindex="-1">Close <a class="header-anchor" href="#close" aria-label="Permalink to &quot;Close&quot;">​</a></h3><ul><li><code>shutdown()</code>: send a FIN frame (<code>seq = next_seq</code>, into the retransmit queue), wait for <code>ack &gt; fin_seq</code></li><li>5s without confirmation: treat the peer as gone, <strong>best-effort close</strong> (no error)</li></ul><h3 id="error-handling" tabindex="-1">Error handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error handling&quot;">​</a></h3><ul><li>Windows <code>WSAECONNRESET(10054)</code> / <code>WSAECONNREFUSED(10061)</code>: ignored (ICMP poisoning)</li><li>Peer socket closed: subsequent recv errors end the session</li></ul><h2 id="_5-tunnel-framing-protocol" tabindex="-1">5. Tunnel framing protocol <a class="header-anchor" href="#_5-tunnel-framing-protocol" aria-label="Permalink to &quot;5. Tunnel framing protocol&quot;">​</a></h2><p>A byte stream over the FRS1 stream (or relay TCP), for local TCP bridging and multi-connection reuse:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Guest → Host: &quot;CNEW&quot;                          # 4 bytes, new connection</span></span>
<span class="line"><span>Guest → Host: [u32 len BE][payload]            # data frame, len ≤ 1 MiB</span></span>
<span class="line"><span>Guest → Host: [u32 0]                          # end frame</span></span>
<span class="line"><span>Host → Guest: [u32 len BE][payload]            # data frame</span></span>
<span class="line"><span>Host → Guest: [u32 0]                          # end frame</span></span></code></pre></div><ul><li>While waiting for <code>CNEW</code>, the host treats any other 4 bytes as a residual data-frame header and skips it (close-race protection)</li><li>End frames are acknowledged symmetrically: on local close, send an end frame and wait for the peer&#39;s; on receiving one, reply (if not already sent) and end the connection</li></ul><h2 id="_6-relay-protocol" tabindex="-1">6. Relay protocol <a class="header-anchor" href="#_6-relay-protocol" aria-label="Permalink to &quot;6. Relay protocol&quot;">​</a></h2><p>TCP text lines (<code>\\r\\n</code> terminated):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client → Server: HELLO &lt;room_id&gt; &lt;HOST|GUEST&gt;</span></span>
<span class="line"><span>Server → Client: WAIT\\r\\n | OK\\r\\n | ERROR &lt;reason&gt;\\r\\n</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Response</th><th>Meaning</th></tr></thead><tbody><tr><td><code>WAIT</code></td><td>slotted, waiting for the peer</td></tr><tr><td><code>OK</code></td><td>peer already waiting, paired</td></tr><tr><td><code>ERROR ROOM_EXPIRED</code> / <code>ERROR BAD_HELLO</code> / <code>ERROR BAD_ROLE</code> / <code>ERROR ALREADY_CONNECTED</code> / <code>ERROR NO_PEER</code></td><td>rejected</td></tr></tbody></table><p>After pairing, the server copies both directions; the ends are transparent. Pairing waits up to 10 minutes.</p><h2 id="compatibility-notes" tabindex="-1">Compatibility notes <a class="header-anchor" href="#compatibility-notes" aria-label="Permalink to &quot;Compatibility notes&quot;">​</a></h2><ul><li>Punching and relay phases use plain ASCII/binary for easy packet debugging</li><li>frp-sh&#39;s protocols are <strong>not compatible</strong> with frp — they are self-designed</li></ul>`,58)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
